  "layout": {
    "globalInputs": [
      "input_time",
      "input_request_id",
      "input_request_path",
      "input_logical_namespace",
      "input_operation",
      "input_host"
    ],
    "layoutDefinitions": {
      "layout_audit": {
        "type": "absolute",
        "options": {
          "width": 1200,
          "height": 2500,
          "display": "auto-scale"
